const token = $input.first().json.access_token;
const allRoms = [];
let platforms = [];

try {
  const pResp = await fetch('http://localhost:8082/api/platforms', {
    headers: { 'Authorization': 'Bearer ' + token, 'Accept': 'application/json' }
  });
  platforms = await pResp.json();
} catch(e) {
  return [{ json: { error: 'Failed to fetch platforms: ' + e.message } }];
}

const withRoms = platforms.filter(p => (p.rom_count || 0) > 0);

for (const platform of withRoms) {
  try {
    let page = 1;
    let hasMore = true;
    while (hasMore) {
      const resp = await fetch(
        `http://localhost:8082/api/roms?platform_id=${platform.id}&limit=100&page=${page}`,
        { headers: { 'Authorization': 'Bearer ' + token, 'Accept': 'application/json' } }
      );
      const data = await resp.json();
      const items = Array.isArray(data) ? data : (data.items || data.results || []);
      for (const rom of items) {
        allRoms.push({
          title: rom.name || rom.file_name || 'Unknown',
          platform: platform.name || platform.slug || 'Unknown',
          genre: (rom.genres || []).map(g => typeof g === 'string' ? g : g.name || ''),
          region: rom.region || '',
          fileName: rom.file_name || '',
          fileSizeMB: Math.round((rom.file_size_bytes || 0) / 1048576),
          hasScreenshot: !!(rom.path_cover_s || rom.path_cover_l || rom.url_screenshots),
          rommId: rom.id,
          platformSlug: platform.slug || ''
        });
      }
      hasMore = items.length === 100;
      page++;
    }
  } catch(e) { /* skip failed platform */ }
}

return [{ json: { items: allRoms, total: allRoms.length, platformCount: withRoms.length } }];

const rommItems = $('Fetch All ROMs').first().json.items;
const notionResults = $('Query Existing Notion Entries').first().json.results || [];

const existingIds = new Map();
for (const page of notionResults) {
  const rommId = page.properties?.['RomM ID']?.number;
  if (rommId) existingIds.set(rommId, page.id);
}

const toCreate = [];
const unchanged = [];
for (const item of rommItems) {
  if (existingIds.has(item.rommId)) {
    unchanged.push(item);
  } else {
    toCreate.push(item);
  }
}

return [{ json: { toCreate, stats: { total: rommItems.length, new: toCreate.length, existing: unchanged.length } } }];

const { toCreate, stats } = $input.first().json;
const notionToken = $env.NOTION_TOKEN;
const dbId = '3da63d55-66c5-8113-a6eb-d2fd60530380';
let created = 0, errors = 0;

for (const item of toCreate.slice(0, 100)) {
  try {
    const body = {
      parent: { database_id: dbId },
      properties: {
        'Title': { title: [{ text: { content: item.title.slice(0, 200) } }] },
        'Platform': { select: { name: item.platform.slice(0, 100) } },
        'Genre': { multi_select: (item.genre || []).slice(0, 10).map(g => ({ name: g.slice(0, 100) })) },
        'Region': item.region ? { select: { name: item.region.slice(0, 100) } } : { select: null },
        'File Name': { rich_text: [{ text: { content: item.fileName.slice(0, 200) } }] },
        'File Size MB': { number: item.fileSizeMB },
        'Has Screenshot': { checkbox: item.hasScreenshot },
        'RomM ID': { number: item.rommId },
        'Status': { select: { name: 'Not Played' } }
      }
    };
    const resp = await fetch('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: { 'Authorization': notionToken, 'Notion-Version': '2022-06-28', 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (resp.ok) created++; else errors++;
  } catch (e) { errors++; }
}

return [{ json: { created, unchanged: stats.existing, errors, total: stats.total } }];

const result = $input.first().json;
console.log(`Games Sync: ${result.created} created, ${result.unchanged} unchanged, ${result.errors} errors (${result.total} total ROMs)`);
return [{ json: result }];
